-- Applied remotely as create_diagnostic_app_v2. Kept here as the source-controlled schema record.
-- See README.md for the app's RLS model and legacy-table migration note.

create schema if not exists private;
create type public.app_role as enum ('tutor', 'admin');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.app_role not null default 'tutor', created_at timestamptz not null default now());
create table public.students (id uuid primary key default gen_random_uuid(), tutor_id uuid not null references public.profiles(id) on delete cascade, full_name text not null check (char_length(full_name) between 1 and 160), created_at timestamptz not null default now());
create table public.assessments (id uuid primary key default gen_random_uuid(), tutor_id uuid not null references public.profiles(id) on delete restrict, student_id uuid not null references public.students(id) on delete restrict, subject text not null check (subject in ('Mathematics', 'English Language')), curriculum text not null, starting_grade text not null, highest_grade_tested text not null, status text not null default 'in_progress' check (status in ('in_progress', 'complete')), tutor_observations text not null default '', created_at timestamptz not null default now(), completed_at timestamptz);
create table public.assessment_events (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id) on delete cascade, grade text not null, topic text not null, level text not null, outcome text not null check (outcome in ('Correct', 'Incorrect', 'Not familiar')), created_at timestamptz not null default now());
create table public.learning_plans (id uuid primary key default gen_random_uuid(), assessment_id uuid not null unique references public.assessments(id) on delete cascade, content jsonb not null, generated_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index assessments_tutor_created_at_idx on public.assessments(tutor_id, created_at desc);
create index assessment_events_assessment_id_idx on public.assessment_events(assessment_id);
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin'); $$;
revoke all on function private.is_admin() from public; grant usage on schema private to authenticated; grant execute on function private.is_admin() to authenticated;
alter table public.profiles enable row level security; alter table public.students enable row level security; alter table public.assessments enable row level security; alter table public.assessment_events enable row level security; alter table public.learning_plans enable row level security;
grant select, insert on public.profiles to authenticated; grant select, insert, update, delete on public.students to authenticated; grant select, insert, update on public.assessments to authenticated; grant select, insert, update, delete on public.assessment_events to authenticated; grant select, insert, update on public.learning_plans to authenticated;
create policy "profiles: insert self" on public.profiles for insert to authenticated with check ((select auth.uid()) = id and role = 'tutor');
create policy "profiles: view self or admin" on public.profiles for select to authenticated using ((select auth.uid()) = id or (select private.is_admin()));
create policy "students: tutor or admin" on public.students for all to authenticated using (tutor_id = (select auth.uid()) or (select private.is_admin())) with check (tutor_id = (select auth.uid()) or (select private.is_admin()));
create policy "assessments: tutor or admin" on public.assessments for all to authenticated using (tutor_id = (select auth.uid()) or (select private.is_admin())) with check (tutor_id = (select auth.uid()) or (select private.is_admin()));
create policy "events: assessment tutor or admin" on public.assessment_events for all to authenticated using ((select private.is_admin()) or exists (select 1 from public.assessments a where a.id = assessment_id and a.tutor_id = (select auth.uid()))) with check ((select private.is_admin()) or exists (select 1 from public.assessments a where a.id = assessment_id and a.tutor_id = (select auth.uid())));
create policy "plans: assessment tutor or admin" on public.learning_plans for all to authenticated using ((select private.is_admin()) or exists (select 1 from public.assessments a where a.id = assessment_id and a.tutor_id = (select auth.uid()))) with check ((select private.is_admin()) or exists (select 1 from public.assessments a where a.id = assessment_id and a.tutor_id = (select auth.uid())));
